DROP TABLE IF EXISTS `submissions`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `submissions` (
  `id` bigint(20) NOT NULL AUTO_INCREMENT,
  `img` longblob NOT NULL,
  `img_type` varchar(255) NOT NULL,
  `img_title` varchar(255) NOT NULL,
  `img_desc` varchar(1000) NOT NULL,
  `approval_emp_id` int(11) NOT NULL,
  `approved_category` bigint(20) NOT NULL,
  `email` varchar(255) NOT NULL,
  `admin_review` int(11) DEFAULT NULL,
  `admin_touch` int(11) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `submissions_approval_emp_id_8f15132a_fk_employee_employee_id` (`approval_emp_id`),
  KEY `submissions_approved_category_07b00682_fk_category_id` (`approved_category`),
  KEY `submissions_email_d163781e_fk_user_email` (`email`),
  KEY `submissions_admin_review_ae623ecc_fk_admin_admin_id` (`admin_review`),
  CONSTRAINT `submissions_admin_review_ae623ecc_fk_admin_admin_id` FOREIGN KEY (`admin_review`) REFERENCES `admin` (`admin_id`),
  CONSTRAINT `submissions_approval_emp_id_8f15132a_fk_employee_employee_id` FOREIGN KEY (`approval_emp_id`) REFERENCES `employee` (`employee_id`),
  CONSTRAINT `submissions_approved_category_07b00682_fk_category_id` FOREIGN KEY (`approved_category`) REFERENCES `category` (`id`),
  CONSTRAINT `submissions_email_d163781e_fk_user_email` FOREIGN KEY (`email`) REFERENCES `user` (`email`)
) ENGINE=InnoDB AUTO_INCREMENT=12 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_uca1400_ai_ci;
